package move

import (
	"bufio"
	"os"
	"regexp"
	"sort"
	"strings"
	"testing"
)

type schemaTable struct {
	cols []string
}

// parseSchema reads db/schema.sql (generated by scripts/schema.sh): the
// tables with their columns, and the sequences.
func parseSchema(t *testing.T) (map[string]schemaTable, []string) {
	t.Helper()
	f, err := os.Open("../../db/schema.sql")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	tables := map[string]schemaTable{}
	var seqs []string
	create := regexp.MustCompile(`^CREATE TABLE public\.(\w+) \($`)
	seq := regexp.MustCompile(`^\s*(?:CREATE SEQUENCE|SEQUENCE NAME) public\.(\w+)`)
	var cur string
	var st schemaTable
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		line := sc.Text()
		switch {
		case cur == "":
			if m := create.FindStringSubmatch(line); m != nil {
				cur, st = m[1], schemaTable{}
			} else if m := seq.FindStringSubmatch(line); m != nil {
				seqs = append(seqs, m[1])
			}
		case line == ");":
			tables[cur] = st
			cur = ""
		default:
			l := strings.TrimSpace(line)
			if strings.HasPrefix(l, "CONSTRAINT") || l == "" {
				continue
			}
			st.cols = append(st.cols, strings.Fields(l)[0])
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	if len(tables) < 50 {
		t.Fatalf("parsed only %d tables from db/schema.sql", len(tables))
	}
	return tables, seqs
}

// TestRegistryCoversSchema is the drift test: a new table, a new sealed
// (*_enc) column or a new sequence must be decided here, or the move would
// silently lose it (LAUN-248).
func TestRegistryCoversSchema(t *testing.T) {
	tables, seqs := parseSchema(t)
	inRegistry := map[string]bool{}
	for _, r := range Registry {
		if inRegistry[r.Name] {
			t.Errorf("table %s is in the registry twice", r.Name)
		}
		inRegistry[r.Name] = true
		if _, ok := tables[r.Name]; !ok {
			t.Errorf("registry names table %s, which is not in the schema", r.Name)
		}
	}
	var missing []string
	for name := range tables {
		if !inRegistry[name] {
			missing = append(missing, name)
		}
	}
	sort.Strings(missing)
	if len(missing) > 0 {
		t.Errorf("tables missing from move.Registry (decide copy, copy+reseal or skip): %v", missing)
	}

	for _, r := range Registry {
		st, ok := tables[r.Name]
		if !ok {
			continue
		}
		sealed := map[string]bool{}
		for _, s := range r.Sealed {
			sealed[s.Column] = true
			if !contains(st.cols, s.Column) {
				t.Errorf("%s: sealed column %s is not in the schema", r.Name, s.Column)
			}
			if !strings.HasSuffix(s.Column, "_enc") {
				t.Errorf("%s.%s: sealed columns end in _enc", r.Name, s.Column)
			}
			if s.Ring != ringSettings && s.Scope == nil {
				t.Errorf("%s.%s: ring %s needs a Scope", r.Name, s.Column, s.Ring)
			}
		}
		if r.Mode == ModeSkip {
			if len(r.Sealed) > 0 || r.Why == "" {
				t.Errorf("%s: a skipped table has no sealed list and gives a reason", r.Name)
			}
			continue
		}
		if (r.Mode == ModeCopyReseal) != (len(r.Sealed) > 0) {
			t.Errorf("%s: mode copy+reseal if and only if it lists sealed columns", r.Name)
		}
		for _, c := range st.cols {
			if strings.HasSuffix(c, "_enc") && !sealed[c] {
				t.Errorf("%s.%s is a sealed column the registry does not list", r.Name, c)
			}
		}
		for _, d := range r.Deferred {
			if !contains(st.cols, d.Column) {
				t.Errorf("%s: deferred column %s is not in the schema", r.Name, d.Column)
			}
		}
	}

	known := map[string]bool{}
	for _, s := range Sequences {
		known[s.Name] = true
	}
	for _, s := range seqs {
		if !known[s] {
			t.Errorf("sequence %s is not in move.Sequences", s)
		}
	}
	for _, s := range ObjectSources {
		st := tables[s.Table]
		if !contains(st.cols, s.KeyColumn) || !contains(st.cols, s.TypeColumn) {
			t.Errorf("object source %s.%s is not in the schema", s.Table, s.KeyColumn)
		}
	}
}

// TestRegistryNeverCopiesSecretsToSkip documents the rule that a login or
// setup credential never travels.
func TestRegistrySkipsCredentials(t *testing.T) {
	for _, name := range []string{"login_codes", "setup_tokens", "idempotency_keys"} {
		r, ok := registryTable(name)
		if !ok || r.Mode != ModeSkip {
			t.Errorf("%s must be skipped", name)
		}
	}
	r, _ := registryTable("api_tokens")
	if r.Mode != ModeCopy || !strings.Contains(r.Where, "session") {
		t.Error("api_tokens copies token hashes and excludes web sessions")
	}
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

func TestSortedCopiedOrdersByForeignKeys(t *testing.T) {
	deps := map[string][]string{
		"issues":          {"teams", "orgs", "users", "issues"},
		"teams":           {"orgs", "workflow_states"},
		"orgs":            {"teams"},
		"workflow_states": {"teams"},
		"org_members":     {"orgs", "users"},
		"backup_runs":     {"backup_destinations"},
	}
	out, err := sortedCopied(deps)
	if err != nil {
		t.Fatal(err)
	}
	pos := map[string]int{}
	for i, tb := range out {
		pos[tb.Name] = i
	}
	for _, p := range [][2]string{{"orgs", "teams"}, {"teams", "workflow_states"}, {"teams", "issues"}, {"users", "org_members"}, {"orgs", "org_members"}} {
		if pos[p[0]] >= pos[p[1]] {
			t.Errorf("%s must come before %s", p[0], p[1])
		}
	}
	for _, tb := range out {
		if tb.Mode == ModeSkip {
			t.Errorf("skipped table %s in the order", tb.Name)
		}
	}
}
